#include "virtual_broadcast/broadcaster/named_pipe_server.hpp"
#include "virtual_broadcast/common/log.hpp"
#include "virtual_broadcast/common/runtime_config.hpp"
#include <algorithm>
#include <array>
namespace vb {namespace {
bool ReadExact(HANDLE h,std::span<std::uint8_t>b){std::size_t n=0;while(n<b.size()){DWORD x=0;if(!ReadFile(h,b.data()+n,static_cast<DWORD>(b.size()-n),&x,nullptr)||!x)return false;n+=x;}return true;}
bool WriteExact(HANDLE h,std::span<const std::uint8_t>b){std::size_t n=0;while(n<b.size()){DWORD x=0;if(!WriteFile(h,b.data()+n,static_cast<DWORD>(b.size()-n),&x,nullptr)||!x)return false;n+=x;}return true;}
HANDLE NewPipe(const std::wstring&name,DWORD access){return CreateNamedPipeW(FullPipeName(name).c_str(),access,PIPE_TYPE_BYTE|PIPE_READMODE_BYTE|PIPE_WAIT,PIPE_UNLIMITED_INSTANCES,65536,65536,0,nullptr);}
void Put32(std::vector<std::uint8_t>&b,std::uint32_t v){for(int i=0;i<4;++i)b.push_back((v>>(i*8))&255);}
}
ClientSession::ClientSession(std::uint64_t id,HANDLE pipe,std::uint32_t channel):client_id_(id),selected_channel_(channel),pipe_(pipe){}
ClientSession::~ClientSession(){Stop();}void ClientSession::Start(){thread_=std::thread(&ClientSession::Run,this);}
void ClientSession::Stop(){if(stop_.exchange(true))return;ready_.notify_all();if(pipe_!=INVALID_HANDLE_VALUE)CancelIoEx(pipe_,nullptr);if(thread_.joinable())thread_.join();if(pipe_!=INVALID_HANDLE_VALUE){DisconnectNamedPipe(pipe_);CloseHandle(pipe_);pipe_=INVALID_HANDLE_VALUE;}connected_=false;}
void ClientSession::Enqueue(std::span<const std::uint8_t>b){if(!connected_||b.empty())return;std::lock_guard lock(mutex_);if(queue_.size()>=256){queue_.pop_front();Log("VirtualBroadcaster","Client queue overflow: oldest TS chunk dropped");}queue_.emplace_back(b.begin(),b.end());ready_.notify_one();}
void ClientSession::Run(){while(!stop_){std::vector<std::uint8_t>chunk;{std::unique_lock lock(mutex_);ready_.wait(lock,[this]{return stop_||!queue_.empty();});if(stop_)break;chunk=std::move(queue_.front());queue_.pop_front();}if(!WriteExact(pipe_,chunk))break;}connected_=false;Log("VirtualBroadcaster","TS client disconnected id="+std::to_string(client_id_));}
NamedPipeServer::NamedPipeServer(std::wstring control,std::wstring ts,std::vector<pipe::ChannelInfo>channels):control_name_(std::move(control)),ts_name_(std::move(ts)),channels_(std::move(channels)){if(channels_.empty())channels_.push_back({0,0,101,32513,8,20,515142857,30.0F,"Virtual Broadcast"});}
NamedPipeServer::~NamedPipeServer(){Stop();}bool NamedPipeServer::Start(){stop_=false;try{ts_accept_thread_=std::thread(&NamedPipeServer::TsAcceptLoop,this);control_thread_=std::thread(&NamedPipeServer::ControlLoop,this);}catch(...){Stop();return false;}return true;}
void NamedPipeServer::Stop(){if(stop_.exchange(true))return;{std::lock_guard lock(session_mutex_);for(auto h:control_handles_)if(h!=INVALID_HANDLE_VALUE)CancelIoEx(h,nullptr);}for(int i=0;i<2;++i){HANDLE h=CreateFileW(FullPipeName(i?ts_name_:control_name_).c_str(),i?GENERIC_READ:(GENERIC_READ|GENERIC_WRITE),0,nullptr,OPEN_EXISTING,0,nullptr);if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);}if(ts_accept_thread_.joinable())ts_accept_thread_.join();if(control_thread_.joinable())control_thread_.join();for(auto&t:control_sessions_)if(t.joinable())t.join();std::vector<std::shared_ptr<ClientSession>>s;{std::lock_guard lock(session_mutex_);s.swap(sessions_);}for(auto&x:s)x->Stop();}
void NamedPipeServer::Broadcast(std::span<const std::uint8_t>b){Broadcast(0,b);}void NamedPipeServer::Broadcast(std::uint32_t channel,std::span<const std::uint8_t>b){std::vector<std::shared_ptr<ClientSession>>s;{std::lock_guard lock(session_mutex_);std::erase_if(sessions_,[](const auto&x){return!x->connected();});s=sessions_;}for(auto&x:s)if(x->selected_channel()==channel)x->Enqueue(b);bytes_sent_+=b.size();}
void NamedPipeServer::TsAcceptLoop(){while(!stop_){HANDLE p=NewPipe(ts_name_,PIPE_ACCESS_OUTBOUND);if(p==INVALID_HANDLE_VALUE)break;Log("VirtualBroadcaster","TS pipe created");const BOOL ok=ConnectNamedPipe(p,nullptr)?TRUE:GetLastError()==ERROR_PIPE_CONNECTED;if(!ok||stop_){CloseHandle(p);continue;}std::uint64_t id;std::uint32_t ch;std::shared_ptr<ClientSession>s;{std::lock_guard lock(session_mutex_);if(!pending_ts_.empty()){id=pending_ts_.front();pending_ts_.pop_front();ch=selections_[id];}else{id=next_client_id_++;selections_[id]=0;ch=0;}s=std::make_shared<ClientSession>(id,p,ch);sessions_.push_back(s);}s->Start();Log("VirtualBroadcaster","TS client connected id="+std::to_string(id));}}
void NamedPipeServer::ControlLoop(){while(!stop_){HANDLE p=NewPipe(control_name_,PIPE_ACCESS_DUPLEX);if(p==INVALID_HANDLE_VALUE)break;Log("VirtualBroadcaster","Control pipe created");const BOOL ok=ConnectNamedPipe(p,nullptr)?TRUE:GetLastError()==ERROR_PIPE_CONNECTED;if(ok&&!stop_){std::lock_guard lock(session_mutex_);control_handles_.push_back(p);control_sessions_.emplace_back(&NamedPipeServer::HandleControl,this,p);}else CloseHandle(p);}}
void NamedPipeServer::HandleControl(HANDLE p){control_client_=p;const auto id=next_client_id_++;{std::lock_guard lock(session_mutex_);selections_[id]=0;}std::array<std::uint8_t,16>raw{};while(!stop_&&ReadExact(p,raw)){pipe::Header h{};pipe::Error error=pipe::Error::Ok;std::vector<std::uint8_t>request;if(!pipe::DecodeHeader(raw,h))error=pipe::Error::BadMagic;else if(h.version!=pipe::kVersion)error=pipe::Error::UnsupportedVersion;else{request.resize(h.payload_size);if(!ReadExact(p,request))break;}std::vector<std::uint8_t>extra;if(error==pipe::Error::Ok){switch(h.type){case pipe::Message::Hello:case pipe::Message::GetVersion:case pipe::Message::Close:case pipe::Message::Purge:case pipe::Message::GetStatus:break;case pipe::Message::Open:{std::lock_guard lock(session_mutex_);pending_ts_.push_back(id);break;}case pipe::Message::EnumChannels:extra=pipe::EncodeChannels(channels_);break;case pipe::Message::GetChannelInfo:{if(request.size()!=4)error=pipe::Error::InvalidPayload;else{const auto ch=pipe::DecodeU32(request);auto i=std::find_if(channels_.begin(),channels_.end(),[&](auto&x){return x.channel==ch;});if(i==channels_.end())error=pipe::Error::Unavailable;else extra=pipe::EncodeChannels(std::span<const pipe::ChannelInfo>(&*i,1));}break;}case pipe::Message::SetChannel:{if(request.size()!=4)error=pipe::Error::InvalidPayload;else{const auto ch=pipe::DecodeU32(request);if(std::none_of(channels_.begin(),channels_.end(),[&](auto&x){return x.space==0&&x.channel==ch;}))error=pipe::Error::Unavailable;else{std::lock_guard lock(session_mutex_);selections_[id]=ch;for(auto&s:sessions_)if(s->client_id()==id)s->Select(ch);}}break;}default:error=pipe::Error::UnknownMessage;}}
    std::vector<std::uint8_t>payload;Put32(payload,static_cast<std::uint32_t>(error));Put32(payload,pipe::kVersion);payload.insert(payload.end(),extra.begin(),extra.end());pipe::Header response{pipe::kVersion,h.type,static_cast<std::uint32_t>(payload.size()),h.request_id};const auto encoded=pipe::EncodeHeader(response);if(!WriteExact(p,encoded)||!WriteExact(p,payload))break;}
  {std::lock_guard lock(session_mutex_);selections_.erase(id);std::replace(control_handles_.begin(),control_handles_.end(),p,INVALID_HANDLE_VALUE);}DisconnectNamedPipe(p);CloseHandle(p);control_client_=INVALID_HANDLE_VALUE;Log("VirtualBroadcaster","Control client disconnected");}
}
